 Bitmap image;GridCropView crop;EditText monday;String times;List<JSONObject> draft=new ArrayList<>();List<CheckBox> picks=new ArrayList<>();boolean busy,saved,schoolSource,examSource;int automaticImages;LocalDate chosenMonday,recognizedMonday;List<Uri> sources=new ArrayList<>();int sourceIndex;AutoGrid.Result located;List<LocalOcr.Block> currentBlocks=new ArrayList<>();
