 void choose(){LinearLayout root=Ui.screen(this,"截图导入课表");LinearLayout intro=Ui.card(this,root);intro.addView(Ui.text(this,"选截图，自动找课程",23));intro.addView(Ui.hint(this,"支持一次多选。支持周课表和实验预约列表。自动定位网格，不用先拖动对齐；自动排除“待核对”“回本周”等按钮文字。"));Ui.primary(this,intro,"选择课表截图",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,101);});LinearLayout help=Ui.fold(this,root,"截图怎么选？");help.addView(Ui.hint(this,"周课表请保留日期和周一至周日；实验预约列表请保留学期、周次、星期、节次、项目和实验室。学期总览可能重叠课程，无法确定具体上课日期。图片在本机识别，不上传、不复制原图。"));}
 static List<Uri> selectedUris(Intent data){LinkedHashSet<Uri> set=new LinkedHashSet<>();if(data!=null){ClipData clip=data.getClipData();if(clip!=null)for(int n=0;n<clip.getItemCount();n++){Uri uri=clip.getItemAt(n).getUri();if(uri!=null)set.add(uri);}if(data.getData()!=null)set.add(data.getData());}return new ArrayList<>(set);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=101||result!=RESULT_OK||data==null)return;List<Uri> chosen=selectedUris(data);if(chosen.isEmpty())return;if(chosen.size()>30){Ui.error(this,new Exception("每批最多30张，请分批导入"));return;}sources=chosen;sourceIndex=0;saved=false;draft.clear();automaticImages=0;loadImage();}
