 void loadImage(){Ui.screen(this,"正在读取截图");releaseImage();recognizedMonday=null;chosenMonday=null;monday=null;located=null;currentBlocks.clear();if(sourceIndex>=sources.size()){review();return;}try{Uri uri=sources.get(sourceIndex);BitmapFactory.Options opt=new BitmapFactory.Options();opt.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(in,null,opt);}if(opt.outWidth<=0)throw new IOException("不能读取这张图片");opt.inSampleSize=1;while(opt.outWidth/opt.inSampleSize>2500||opt.outHeight/opt.inSampleSize>3000)opt.inSampleSize*=2;opt.inJustDecodeBounds=false;try(InputStream in=getContentResolver().openInputStream(uri)){image=BitmapFactory.decodeStream(in,null,opt);}if(image==null)throw new IOException("图片加载失败");analyze(false);}catch(Exception error){new AlertDialog.Builder(this).setMessage("第"+(sourceIndex+1)+"张加载失败："+error.getMessage()).setPositiveButton("重试",(d,w)->loadImage()).setNegativeButton("跳过",(d,w)->nextImage()).show();}}
