 void analyze(boolean manual){if(busy)return;final Rect manualGrid=manual?crop.grid():null;final int manualRows=manual?crop.rows:0;busy=true;LinearLayout root=Ui.screen(this,"自动识别课表");root.addView(Ui.hint(this,step()));LinearLayout panel=Ui.card(this,root);panel.addView(Ui.text(this,"正在找出课程",22));ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setIndeterminate(true);panel.addView(bar,new LinearLayout.LayoutParams(-1,Ui.dp(this,8)));TextView state=Ui.hint(this,"定位课表网格…");panel.addView(state);
  new Thread(()->{try{if(!manual){LabSchedule.Result labs=LabSchedule.read(this,image,text->runOnUiThread(()->{if(!isDestroyed())state.setText(text);}));if(labs!=null){runOnUiThread(()->{busy=false;if(isDestroyed()||isFinishing()){releaseImage();return;}acceptLabList(labs);});return;}}AutoGrid.Result detected=manual?new AutoGrid.Result(manualGrid,manualRows,true):AutoGrid.locate(image,parseTimes(times).size());if(!detected.reliable){runOnUiThread(()->{busy=false;if(isDestroyed()||isFinishing()){releaseImage();return;}located=detected;configure();});return;}located=detected;
   String header="";try{header=LocalOcr.header(this,image,detected.grid.top);}catch(Exception ignored){}if(!manual&&LocalOcr.semesterOverview(image,header)){runOnUiThread(()->{busy=false;if(isDestroyed()||isFinishing()){releaseImage();return;}LinearLayout notice=Ui.screen(this,"请使用周课表");notice.addView(Ui.text(this,"这张是学期总览",22));notice.addView(Ui.hint(this,"学期总览会重叠不同周的课程，无法确定具体日期。请在教务页面切到“周课表”后截图。"));Ui.primary(this,notice,"跳过这张，继续",this::nextImage);});return;}setImageDate(header);if(recognizedMonday==null)try{setImageDate(header+"\n"+LocalOcr.columnDates(this,image,detected.grid));}catch(Exception ignored){}
   List<LocalOcr.Block> found=LocalOcr.read(this,image,detected.grid,detected.rows,detected.rowHeight,text->runOnUiThread(()->{if(!isDestroyed())state.setText(text);}));runOnUiThread(()->{busy=false;if(isDestroyed()||isFinishing()){releaseImage();return;}currentBlocks=found;imageRecognized();});
  }catch(Throwable error){runOnUiThread(()->{busy=false;if(isDestroyed()||isFinishing()){releaseImage();return;}LinearLayout retry=Ui.screen(this,"暂未识别成功");retry.addView(Ui.hint(this,"本批之前的结果仍保留。可重新识别或调整范围。"));Ui.primary(this,retry,"重新自动识别",()->analyze(false));Ui.button(this,retry,"手动调整范围",this::configure);Ui.link(this,retry,"跳过这张",this::nextImage);LinearLayout info=Ui.fold(this,retry,"查看原因");info.addView(Ui.hint(this,String.valueOf(error.getMessage())));});}},"automatic-timetable").start();
 }

 void acceptLabList(LabSchedule.Result labs){try{if(labs.records.isEmpty())throw new IllegalArgumentException("实验课文字未读完整，请保留每条的周次、星期、项目、节次和实验室后重新截图。");Map<String,LocalDate> anchors=new HashMap<>();for(LabSchedule.Record r:labs.records){LocalDate first=LabSchedule.anchor(this,r.term);if(first==null){requestLabAnchor(labs,r.term);return;}anchors.put(r.term,first);}JSONArray events=LabSchedule.events(this,labs,anchors,times,sourceIndex+1);for(int n=0;n<events.length();n++)draft.add(events.getJSONObject(n));automaticImages++;if(labs.incomplete>0)new AlertDialog.Builder(this).setTitle("已识别 "+events.length()+" 条实验课").setMessage("有 "+labs.incomplete+" 条文字不完整，未自动生成，可在新增课程页补加。已识别的日期按各自周次换算，不会全部放到同一周。").setPositiveButton("继续",(d,w)->nextImage()).show();else nextImage();}catch(Exception error){Ui.error(this,error);configureLabRetry();}}
 void requestLabAnchor(LabSchedule.Result labs,String term){LinearLayout root=Ui.screen(this,"确定实验课的学期日期");root.addView(Ui.text(this,term+" 学期",22));root.addView(Ui.hint(this,"截图只有周次，没有日历日期，本机也没有可用的校历依据。只需确定一次该学期第1周的周一，后续截图会自动换算全部周次。也可以先通过学校账号导入课表，再重新导入此图。"));Ui.primary(this,root,"选择学期第1周周一",()->{LocalDate initial=LocalDate.of(Integer.parseInt(term.substring(0,4))+(term.endsWith("-2")?1:0),term.endsWith("-2")?2:9,1);new DatePickerDialog(this,(v,y,m,d)->{LocalDate selected=LocalDate.of(y,m+1,d);if(!LabSchedule.validAnchor(term,selected)){Ui.error(this,new Exception("请选择对应学期第1周的周一日期，不会使用当前周代替。"));return;}Agenda.prefs(this).edit().putString("labTermStart_"+term,selected.toString()).commit();acceptLabList(labs);},initial.getYear(),initial.getMonthValue()-1,initial.getDayOfMonth()).show();});Ui.link(this,root,"跳过这张",this::nextImage);}
